import time

def call_with_retry(fn,args,retries=3,base_sleep=1.0):
    for i in range(retries+1):
        res,err=fn(args)
        if not err:
            return res,None
        if '429' not in str(err) and 'over limit' not in str(err):
            return res,err
        time.sleep(base_sleep*(2**i))
    return res,err
